import {detectPieces,guessBackground,removeBorderBackground} from './slice.mjs';
self.onmessage=({data:m})=>{try{const data=new Uint8ClampedArray(m.pixels),background=m.mode==='white'?[255,255,255]:m.mode==='auto'?guessBackground(data,m.width,m.height):null,{pixels,removed}=removeBorderBackground(data,m.width,m.height,{background,tolerance:m.tolerance??28});const boxes=detectPieces(pixels,m.width,m.height,{minArea:m.minArea});self.postMessage({boxes,background,removed,pixels:pixels.buffer},[pixels.buffer])}catch(e){self.postMessage({error:e.message})}};
